/**
 * sitemap.xml (generated by Next.js Metadata API)
 * ===============================================
 * Lists every indexable URL in EVERY language edition, and annotates each entry
 * with its alternates. Next renders `alternates.languages` as `xhtml:link`
 * elements, which is the sitemap-side half of hreflang: Google accepts the
 * signal either in the page head or here, and having both is belt and braces.
 *
 * Routes are derived from `lib/i18n/config` and `lib/projects`, so a new locale
 * or a new project appears here automatically.
 */

import type { MetadataRoute } from "next";
import { LOCALES } from "@/lib/i18n/config";
import { absoluteUrl, languageAlternates } from "@/lib/seo";
import { SITE_URL } from "@/lib/site";
import { getProjectSlugs } from "@/lib/projects";

/** Language-agnostic paths, paired with their crawl priority. */
const STATIC_PATHS: { path: string; priority: number }[] = [
  { path: "/", priority: 1 },
  { path: "/about", priority: 0.8 },
  { path: "/services", priority: 0.8 },
  { path: "/projects", priority: 0.8 },
  { path: "/careers", priority: 0.6 },
  { path: "/suppliers", priority: 0.6 },
];

export default function sitemap(): MetadataRoute.Sitemap {
  const lastModified = new Date();

  const paths = [
    ...STATIC_PATHS,
    ...getProjectSlugs().map((slug) => ({
      path: `/projects/${slug}`,
      priority: 0.8,
    })),
  ];

  // One entry per (path x locale). `languages` carries the absolute URL of each
  // edition, so every entry points at all of its siblings.
  return paths.flatMap(({ path, priority }) => {
    const languages = Object.fromEntries(
      Object.entries(languageAlternates(path)).map(([code, href]) => [
        code,
        `${SITE_URL}${href}`,
      ])
    );

    return LOCALES.map((locale) => ({
      url: absoluteUrl(locale, path),
      lastModified,
      changeFrequency: "monthly" as const,
      priority,
      alternates: { languages },
    }));
  });
}
